var (
	scanner *FastScanner
	writer  *bufio.Writer
)

type FastScanner struct {
	reader *bufio.Reader
	buf    []byte
}

func NewFastScanner(r *bufio.Reader) *FastScanner {
	return &FastScanner{reader: r, buf: make([]byte, 0, 1024)}
}

func (fs *FastScanner) NextInt() int {
	fs.skipSpace()
	sign := 1
	b, _ := fs.reader.ReadByte()
	if b == '-' {
		sign = -1
		b, _ = fs.reader.ReadByte()
	}
	num := 0
	for b >= '0' && b <= '9' {
		num = num*10 + int(b-'0')
		b, _ = fs.reader.ReadByte()
	}
	return num * sign
}

func (fs *FastScanner) NextString() string {
	fs.skipSpace()
	fs.buf = fs.buf[:0]
	b, _ := fs.reader.ReadByte()
	for b != 0 && !isSpace(b) {
		fs.buf = append(fs.buf, b)
		b, _ = fs.reader.ReadByte()
	}
	return string(fs.buf)
}

func (fs *FastScanner) skipSpace() {
	for {
		b, err := fs.reader.ReadByte()
		if err != nil {
			return
		}
		if !isSpace(b) {
			fs.reader.UnreadByte()
			return
		}
	}
}

func isSpace(b byte) bool {
	return b <= ' '
}

func solve() {
	n := scanner.NextInt()
	s := scanner.NextString()
	r := 0
	for i := 1; i < n; i++ {
		if s[i] == s[i-1] {
			r++
		}
	}
	fmt.Fprintln(writer, r)
}

