}

func NewFastScanner(reader *bufio.Reader) *FastScanner {
	return &FastScanner{
		reader: reader,
		buf:    make([]byte, 1024),
		idx:    0,
		size:   0,
	}
}

func (s *FastScanner) readByte() byte {
	if s.idx >= s.size {
		s.idx = 0
		n, err := s.reader.Read(s.buf)
		if err != nil || n == 0 {
			return 0
		}
		s.size = n
	}
	b := s.buf[s.idx]
	s.idx++
	return b
}

func (s *FastScanner) skipSpaces() byte {
	b := s.readByte()
	for b != 0 && (b <= ' ') {
		b = s.readByte()
	}
	return b
}

func (s *FastScanner) NextInt() int {
	b := s.skipSpaces()
	neg := false
	if b == '-' {
		neg = true
		b = s.readByte()
	}
	num := 0
	for b >= '0' && b <= '9' {
		num = num*10 + int(b-'0')
		b = s.readByte()
	}
	if neg {
		return -num
	}
	return num
}

func (s *FastScanner) NextString() string {
	b := s.skipSpaces()
	if b == 0 {
		return ""
	}
	var buf []byte
	for b > ' ' {
		buf = append(buf, b)
		b = s.readByte()
	}
	return string(buf)
}

