	b, err := fs.reader.ReadByte()
	return b, err
}

func (fs *FastScanner) unreadByte() error {
	return fs.reader.UnreadByte()
}

func (fs *FastScanner) skipSpaces() (byte, error) {
	for {
		b, err := fs.readByte()
		if err != nil {
			return 0, err
		}
		if b > 32 { // not space, newline, tab, etc.
			return b, nil
		}
	}
}

func (fs *FastScanner) NextInt() int {
	b, err := fs.skipSpaces()
	if err != nil {
		panic(err)
	}

	neg := false
	if b == '-' {
		neg = true
		b, err = fs.readByte()
		if err != nil {
			panic(err)
		}
	}

	val := 0
	for b >= '0' && b <= '9' {
		val = val*10 + int(b-'0')
		b, err = fs.readByte()
		if err != nil {
			break
		}
	}
	// Put back the non-digit byte
	if err == nil {
		fs.unreadByte()
	}

	if neg {
		return -val
	}
	return val
}

func (fs *FastScanner) NextString() string {
	b, err := fs.skipSpaces()
	if err != nil {
		return ""
	}

	fs.buf = fs.buf[:0]
	fs.buf = append(fs.buf, b)

	for {
		b, err = fs.readByte()
		if err != nil {
			break
		}
		if b <= 32 {
			break
		}
		fs.buf = append(fs.buf, b)
	}

	return string(fs.buf)
}

