	s := in.NextString()
	r := 0
	// Ensure string length matches n, though problem guarantees it.
	// In Go, strings are immutable byte slices essentially.
	for i := 1; i < n; i++ {
		if s[i] == s[i-1] {
			r++
		}
	}
	out.WriteString(itoa(r))
	out.WriteByte('\n')
